insert into public.messinho_language_knowledge
(entry_key,version,language_code,entry_type,topic,title,content,tags,level,knowledge_status,provenance_type,created_by)
values
('de.grammar.main_clause',1,'de','grammar','Satzbau','Verbzweitstellung im Hauptsatz','{"explanation":"Im deutschen Aussagesatz steht das finite Verb normalerweise an zweiter Satzposition. Das erste Satzglied kann Zeit, Ort oder Objekt sein; das Verb bleibt an Position zwei. Im Nebensatz steht das finite Verb typischerweise am Ende.","examples":[{"text":"Der Spieler trainiert heute.","meaning":"Beispiel zur grammatischen oder pragmatischen Anwendung"},{"text":"Heute trainiert der Spieler.","meaning":"Kontextbeispiel"},{"text":"Ich glaube, dass der Spieler heute trainiert.","meaning":"Kontextbeispiel"}],"terms":[],"grammar_notes":[],"aliases":[]}'::jsonb,ARRAY['Hauptsatz','Verbzweit','Nebensatz','Satzklammer'],'foundational','active','original_authored','messinho_original'),
('de.grammar.cases',1,'de','grammar','Kasus','Vier Fälle und ihre Funktionen','{"explanation":"Deutsch markiert Beziehungen im Satz mit Nominativ, Akkusativ, Dativ und Genitiv. Artikel, Pronomen und Adjektive verändern sich abhängig von Genus, Numerus und Kasus. Die Funktion im Satz ist wichtiger als die Wortstellung allein.","examples":[{"text":"Der Trainer sieht den Spieler.","meaning":"Beispiel zur grammatischen oder pragmatischen Anwendung"},{"text":"Der Trainer hilft dem Spieler.","meaning":"Kontextbeispiel"},{"text":"Die Leistung des Spielers ist stark.","meaning":"Kontextbeispiel"}],"terms":[],"grammar_notes":[],"aliases":[]}'::jsonb,ARRAY['Nominativ','Akkusativ','Dativ','Genitiv','Artikel'],'foundational','active','original_authored','messinho_original'),
('de.grammar.verbs',1,'de','grammar','Verbformen','Zeitformen und Modalverben','{"explanation":"Das finite Verb trägt Person und Numerus. Perfekt wird meist mit haben oder sein plus Partizip II gebildet. Modalverben wie können, müssen, dürfen, sollen, wollen und mögen verändern Möglichkeit, Pflicht oder Absicht; der Infinitiv steht häufig am Satzende.","examples":[{"text":"Er hat gut gespielt.","meaning":"Beispiel zur grammatischen oder pragmatischen Anwendung"},{"text":"Sie ist schnell gelaufen.","meaning":"Kontextbeispiel"},{"text":"Der Spieler muss heute trainieren.","meaning":"Kontextbeispiel"}],"terms":[],"grammar_notes":[],"aliases":[]}'::jsonb,ARRAY['Perfekt','Präteritum','Modalverb','Partizip II'],'foundational','active','original_authored','messinho_original'),
('de.lexicon.core',1,'de','lexicon','Grundwortschatz','Häufige Gesprächswörter','{"explanation":"Kompakter, selbst formulierter Startwortschatz für natürliche Gespräche. Bedeutungen hängen vom Kontext ab; einzelne Wörter dürfen nicht ohne Satzkontext eindeutig festgelegt werden.","examples":[],"terms":[{"term":"eigentlich","meaning_de":"Kontextabhängige Bedeutung; im Satz prüfen."},{"term":"vielleicht","meaning_de":"Kontextabhängige Bedeutung; im Satz prüfen."},{"term":"allerdings","meaning_de":"Kontextabhängige Bedeutung; im Satz prüfen."},{"term":"trotzdem","meaning_de":"Kontextabhängige Bedeutung; im Satz prüfen."},{"term":"während","meaning_de":"Kontextabhängige Bedeutung; im Satz prüfen."},{"term":"obwohl","meaning_de":"Kontextabhängige Bedeutung; im Satz prüfen."},{"term":"deshalb","meaning_de":"Kontextabhängige Bedeutung; im Satz prüfen."},{"term":"sowohl","meaning_de":"Kontextabhängige Bedeutung; im Satz prüfen."},{"term":"weder","meaning_de":"Kontextabhängige Bedeutung; im Satz prüfen."},{"term":"noch","meaning_de":"Kontextabhängige Bedeutung; im Satz prüfen."},{"term":"Leistung","meaning_de":"Kontextabhängige Bedeutung; im Satz prüfen."},{"term":"Entwicklung","meaning_de":"Kontextabhängige Bedeutung; im Satz prüfen."},{"term":"Stärke","meaning_de":"Kontextabhängige Bedeutung; im Satz prüfen."},{"term":"Schwäche","meaning_de":"Kontextabhängige Bedeutung; im Satz prüfen."},{"term":"Einschätzung","meaning_de":"Kontextabhängige Bedeutung; im Satz prüfen."}],"grammar_notes":[],"aliases":[]}'::jsonb,ARRAY['eigentlich','vielleicht','allerdings','trotzdem','während','obwohl','deshalb','sowohl','weder','noch','Leistung','Entwicklung','Stärke','Schwäche','Einschätzung'],'foundational','active','original_authored','messinho_original'),
('de.pragmatics.dialogue',1,'de','pragmatics','Gesprächsabsicht','Nuancen und indirekte Aussagen','{"explanation":"Wörter wie eigentlich, noch, zwar, aber und vielleicht können eine Aussage abschwächen, einschränken oder kontrastieren. Eine höfliche Frage ist nicht automatisch ein Befehl. Verneinungen und Einschränkungen müssen bei der Interpretation erhalten bleiben.","examples":[{"text":"Er ist nicht schlecht, aber noch nicht bereit.","meaning":"Beispiel zur grammatischen oder pragmatischen Anwendung"},{"text":"Könntest du das bitte erklären?","meaning":"Kontextbeispiel"},{"text":"Das ist vielleicht eine gute Option.","meaning":"Kontextbeispiel"}],"terms":[],"grammar_notes":[],"aliases":[]}'::jsonb,ARRAY['Abschwächung','Höflichkeit','Kontrast','Implikatur'],'foundational','active','original_authored','messinho_original'),
('en.grammar.word_order',1,'en','grammar','Sentence structure','Subject–verb–object order','{"explanation":"English declarative clauses commonly follow subject–verb–object order. Questions and some subordinate structures change the order or use auxiliary verbs. Adverbs have position constraints and should not be translated word-for-word from German.","examples":[{"text":"The player trains every day.","meaning":"Beispiel zur grammatischen oder pragmatischen Anwendung"},{"text":"Does the player train every day?","meaning":"Kontextbeispiel"},{"text":"The player, who joined last year, is improving.","meaning":"Kontextbeispiel"}],"terms":[],"grammar_notes":[],"aliases":[]}'::jsonb,ARRAY['subject','verb','object','auxiliary','clause'],'foundational','active','original_authored','messinho_original'),
('en.grammar.tense_aspect',1,'en','grammar','Tense and aspect','English tense and aspect','{"explanation":"English distinguishes tense and aspect. Present perfect connects a past event to the present; past simple typically locates a completed event in a finished past time. Continuous forms express an ongoing or temporary process.","examples":[{"text":"He played yesterday.","meaning":"Beispiel zur grammatischen oder pragmatischen Anwendung"},{"text":"He has improved this season.","meaning":"Kontextbeispiel"},{"text":"He is training now.","meaning":"Kontextbeispiel"}],"terms":[],"grammar_notes":[],"aliases":[]}'::jsonb,ARRAY['past simple','present perfect','present continuous','aspect'],'foundational','active','original_authored','messinho_original'),
('en.grammar.articles',1,'en','grammar','Articles and countability','Articles and noun phrases','{"explanation":"English uses a, an and the with countable nouns, while uncountable nouns often behave differently. The choice between definite and indefinite articles depends on whether the referent is identifiable in context.","examples":[{"text":"A player joined the club.","meaning":"Beispiel zur grammatischen oder pragmatischen Anwendung"},{"text":"The player scored twice.","meaning":"Kontextbeispiel"},{"text":"Experience takes time.","meaning":"Kontextbeispiel"}],"terms":[],"grammar_notes":[],"aliases":[]}'::jsonb,ARRAY['article','countable','uncountable','definite','indefinite'],'foundational','active','original_authored','messinho_original'),
('en.lexicon.core',1,'en','lexicon','Core vocabulary','Common conversational vocabulary','{"explanation":"A compact original starter vocabulary for everyday dialogue. Polysemy and idioms require context; the same word can have technical, literal or figurative meanings.","examples":[],"terms":[{"term":"actually","meaning_de":"Kontextabhängige Bedeutung; im Satz prüfen."},{"term":"rather","meaning_de":"Kontextabhängige Bedeutung; im Satz prüfen."},{"term":"although","meaning_de":"Kontextabhängige Bedeutung; im Satz prüfen."},{"term":"however","meaning_de":"Kontextabhängige Bedeutung; im Satz prüfen."},{"term":"unless","meaning_de":"Kontextabhängige Bedeutung; im Satz prüfen."},{"term":"despite","meaning_de":"Kontextabhängige Bedeutung; im Satz prüfen."},{"term":"still","meaning_de":"Kontextabhängige Bedeutung; im Satz prüfen."},{"term":"already","meaning_de":"Kontextabhängige Bedeutung; im Satz prüfen."},{"term":"yet","meaning_de":"Kontextabhängige Bedeutung; im Satz prüfen."},{"term":"likely","meaning_de":"Kontextabhängige Bedeutung; im Satz prüfen."},{"term":"performance","meaning_de":"Kontextabhängige Bedeutung; im Satz prüfen."},{"term":"development","meaning_de":"Kontextabhängige Bedeutung; im Satz prüfen."},{"term":"strength","meaning_de":"Kontextabhängige Bedeutung; im Satz prüfen."},{"term":"weakness","meaning_de":"Kontextabhängige Bedeutung; im Satz prüfen."},{"term":"assessment","meaning_de":"Kontextabhängige Bedeutung; im Satz prüfen."}],"grammar_notes":[],"aliases":[]}'::jsonb,ARRAY['actually','rather','although','however','unless','despite','still','already','yet','likely','performance','development','strength','weakness','assessment'],'foundational','active','original_authored','messinho_original'),
('en.pragmatics.dialogue',1,'en','pragmatics','Dialogue intent','Hedges, politeness and implication','{"explanation":"Words such as actually, rather, still, yet, perhaps and however can soften, qualify or contrast a statement. Questions may be indirect requests. Preserve negation and uncertainty instead of converting them into certainty.","examples":[{"text":"He is good, but not ready yet.","meaning":"Beispiel zur grammatischen oder pragmatischen Anwendung"},{"text":"Could you explain that, please?","meaning":"Kontextbeispiel"},{"text":"That might be a useful option.","meaning":"Kontextbeispiel"}],"terms":[],"grammar_notes":[],"aliases":[]}'::jsonb,ARRAY['hedging','politeness','contrast','implicature'],'foundational','active','original_authored','messinho_original'),
('fr.grammar.word_order',1,'fr','grammar','Syntaxe','Ordre des mots','{"explanation":"La phrase déclarative française suit généralement l’ordre sujet–verbe–complément. Les pronoms compléments se placent souvent avant le verbe. La négation standard encadre le verbe avec ne et pas, même si ne est souvent omis à l’oral.","examples":[{"text":"Le joueur travaille.","meaning":"Beispiel zur grammatischen oder pragmatischen Anwendung"},{"text":"Je le connais.","meaning":"Kontextbeispiel"},{"text":"Il ne joue pas aujourd’hui.","meaning":"Kontextbeispiel"}],"terms":[],"grammar_notes":[],"aliases":[]}'::jsonb,ARRAY['sujet','verbe','complément','pronoms','négation'],'foundational','active','original_authored','messinho_original'),
('fr.grammar.gender_agreement',1,'fr','grammar','Genre et accord','Genre, nombre et accord','{"explanation":"Les noms sont généralement masculins ou féminins. Les déterminants et les adjectifs s’accordent en genre et en nombre avec le nom. Le genre grammatical ne doit pas être confondu avec une caractéristique réelle de la personne.","examples":[{"text":"un joueur rapide","meaning":"Beispiel zur grammatischen oder pragmatischen Anwendung"},{"text":"une joueuse rapide","meaning":"Kontextbeispiel"},{"text":"des joueurs rapides","meaning":"Kontextbeispiel"}],"terms":[],"grammar_notes":[],"aliases":[]}'::jsonb,ARRAY['masculin','féminin','singulier','pluriel','accord'],'foundational','active','original_authored','messinho_original'),
('fr.grammar.verbs',1,'fr','grammar','Conjugaison','Personne et temps verbaux','{"explanation":"Le verbe se conjugue selon la personne, le nombre, le temps et le mode. Le présent, le passé composé et l’imparfait ont des fonctions différentes. Les auxiliaires avoir et être participent à la formation du passé composé.","examples":[{"text":"Il joue.","meaning":"Beispiel zur grammatischen oder pragmatischen Anwendung"},{"text":"Il a joué.","meaning":"Kontextbeispiel"},{"text":"Quand il était jeune, il jouait souvent.","meaning":"Kontextbeispiel"}],"terms":[],"grammar_notes":[],"aliases":[]}'::jsonb,ARRAY['présent','passé composé','imparfait','auxiliaire','conjugaison'],'foundational','active','original_authored','messinho_original'),
('fr.lexicon.core',1,'fr','lexicon','Vocabulaire courant','Mots fréquents de conversation','{"explanation":"Petit vocabulaire original pour comprendre les échanges. Le sens d’un mot dépend de la situation, du registre et des expressions idiomatiques.","examples":[],"terms":[{"term":"pourtant","meaning_de":"Kontextabhängige Bedeutung; im Satz prüfen."},{"term":"cependant","meaning_de":"Kontextabhängige Bedeutung; im Satz prüfen."},{"term":"plutôt","meaning_de":"Kontextabhängige Bedeutung; im Satz prüfen."},{"term":"encore","meaning_de":"Kontextabhängige Bedeutung; im Satz prüfen."},{"term":"déjà","meaning_de":"Kontextabhängige Bedeutung; im Satz prüfen."},{"term":"peut-être","meaning_de":"Kontextabhängige Bedeutung; im Satz prüfen."},{"term":"d’ailleurs","meaning_de":"Kontextabhängige Bedeutung; im Satz prüfen."},{"term":"même si","meaning_de":"Kontextabhängige Bedeutung; im Satz prüfen."},{"term":"donc","meaning_de":"Kontextabhängige Bedeutung; im Satz prüfen."},{"term":"en revanche","meaning_de":"Kontextabhängige Bedeutung; im Satz prüfen."},{"term":"performance","meaning_de":"Kontextabhängige Bedeutung; im Satz prüfen."},{"term":"progrès","meaning_de":"Kontextabhängige Bedeutung; im Satz prüfen."},{"term":"qualité","meaning_de":"Kontextabhängige Bedeutung; im Satz prüfen."},{"term":"faiblesse","meaning_de":"Kontextabhängige Bedeutung; im Satz prüfen."},{"term":"évaluation","meaning_de":"Kontextabhängige Bedeutung; im Satz prüfen."}],"grammar_notes":[],"aliases":[]}'::jsonb,ARRAY['pourtant','cependant','plutôt','encore','déjà','peut-être','d’ailleurs','même si','donc','en revanche','performance','progrès','qualité','faiblesse','évaluation'],'foundational','active','original_authored','messinho_original'),
('fr.pragmatics.dialogue',1,'fr','pragmatics','Pragmatique','Nuance et politesse','{"explanation":"Des mots comme pourtant, plutôt, encore, peut-être et cependant expriment une réserve, une opposition ou une incertitude. Une question polie peut être une demande indirecte. Il faut conserver les négations et les nuances.","examples":[{"text":"Il est bon, mais pas encore prêt.","meaning":"Beispiel zur grammatischen oder pragmatischen Anwendung"},{"text":"Pourriez-vous expliquer cela ?","meaning":"Kontextbeispiel"},{"text":"C’est peut-être une bonne solution.","meaning":"Kontextbeispiel"}],"terms":[],"grammar_notes":[],"aliases":[]}'::jsonb,ARRAY['atténuation','politesse','opposition','implicite'],'foundational','active','original_authored','messinho_original'),
('ar.grammar.word_order',1,'ar','grammar','تركيب الجملة','ترتيب الكلمات في العربية الفصحى','{"explanation":"في العربية الفصحى يمكن أن تبدأ الجملة بالفعل أو بالاسم. الجملة الفعلية تبدأ غالباً بالفعل، والجملة الاسمية تبدأ غالباً بالاسم أو المبتدأ. يتغير الإعراب بحسب وظيفة الكلمة في الجملة.","examples":[{"text":"كتب اللاعب التقرير.","meaning":"Beispiel zur grammatischen oder pragmatischen Anwendung"},{"text":"اللاعب سريع.","meaning":"Kontextbeispiel"},{"text":"إن اللاعب مجتهد.","meaning":"Kontextbeispiel"}],"terms":[],"grammar_notes":[],"aliases":[]}'::jsonb,ARRAY['جملة فعلية','جملة اسمية','فعل','فاعل','مبتدأ','خبر'],'foundational','active','original_authored','messinho_original'),
('ar.grammar.morphology',1,'ar','grammar','الصرف','الجذر والوزن','{"explanation":"تعتمد العربية على جذور صرفية وأوزان تساعد على تكوين كلمات مترابطة في المعنى. الجذر الثلاثي شائع، لكن لا يجوز استنتاج معنى دقيق من الجذر وحده دون معرفة الوزن والسياق والاستعمال.","examples":[{"text":"ك ت ب: كتب، كتاب، مكتبة","meaning":"Beispiel zur grammatischen oder pragmatischen Anwendung"},{"text":"ع ل م: علم، تعليم، معلومة","meaning":"Kontextbeispiel"}],"terms":[],"grammar_notes":[],"aliases":[]}'::jsonb,ARRAY['جذر','وزن','اشتقاق','صيغة'],'foundational','active','original_authored','messinho_original'),
('ar.grammar.agreement',1,'ar','grammar','المطابقة','التذكير والتأنيث والعدد','{"explanation":"تتأثر الصفة والفعل والضمير بالجنس والعدد والشخص. قواعد المطابقة في العربية لها تفاصيل تختلف بحسب موقع الاسم وترتيبه، والمفرد والمثنى والجمع، والعاقل وغير العاقل.","examples":[{"text":"لاعب سريع.","meaning":"Beispiel zur grammatischen oder pragmatischen Anwendung"},{"text":"لاعبة سريعة.","meaning":"Kontextbeispiel"},{"text":"اللاعبان سريعان.","meaning":"Kontextbeispiel"}],"terms":[],"grammar_notes":[],"aliases":[]}'::jsonb,ARRAY['مذكر','مؤنث','مفرد','مثنى','جمع','مطابقة'],'foundational','active','original_authored','messinho_original'),
('ar.lexicon.core',1,'ar','lexicon','مفردات أساسية','كلمات شائعة في الحوار','{"explanation":"مجموعة أولية أصلية من الكلمات الشائعة. يجب فهم الكلمة داخل الجملة واللهجة والسياق، ولا ينبغي اعتبار الفصحى مرادفة للهجات العربية.","examples":[],"terms":[{"term":"مرحبا","meaning_de":"Kontextabhängige Bedeutung; im Satz prüfen."},{"term":"شكرا","meaning_de":"Kontextabhängige Bedeutung; im Satz prüfen."},{"term":"من فضلك","meaning_de":"Kontextabhängige Bedeutung; im Satz prüfen."},{"term":"لكن","meaning_de":"Kontextabhängige Bedeutung; im Satz prüfen."},{"term":"ربما","meaning_de":"Kontextabhängige Bedeutung; im Satz prüfen."},{"term":"مع ذلك","meaning_de":"Kontextabhängige Bedeutung; im Satz prüfen."},{"term":"اليوم","meaning_de":"Kontextabhängige Bedeutung; im Satz prüfen."},{"term":"غدا","meaning_de":"Kontextabhängige Bedeutung; im Satz prüfen."},{"term":"لاعب","meaning_de":"Kontextabhängige Bedeutung; im Satz prüfen."},{"term":"فريق","meaning_de":"Kontextabhängige Bedeutung; im Satz prüfen."},{"term":"قوة","meaning_de":"Kontextabhängige Bedeutung; im Satz prüfen."},{"term":"مهارة","meaning_de":"Kontextabhängige Bedeutung; im Satz prüfen."},{"term":"تطور","meaning_de":"Kontextabhängige Bedeutung; im Satz prüfen."},{"term":"تقييم","meaning_de":"Kontextabhängige Bedeutung; im Satz prüfen."},{"term":"أداء","meaning_de":"Kontextabhängige Bedeutung; im Satz prüfen."}],"grammar_notes":[],"aliases":[]}'::jsonb,ARRAY['مرحبا','شكرا','من فضلك','لكن','ربما','مع ذلك','اليوم','غدا','لاعب','فريق','قوة','مهارة','تطور','تقييم','أداء'],'foundational','active','original_authored','messinho_original'),
('ar.pragmatics.dialogue',1,'ar','pragmatics','التداولية','المعنى والسياق والتهذيب','{"explanation":"قد تحمل صيغة السؤال معنى الطلب أو الاقتراح. كلمات مثل ربما ولكن ومع ذلك تخفف الحكم أو تضيف قيدا. يجب الحفاظ على النفي والاحتمال والاحترام في الرد.","examples":[{"text":"هو لاعب جيد، لكنه غير جاهز بعد.","meaning":"Beispiel zur grammatischen oder pragmatischen Anwendung"},{"text":"هل يمكنك التوضيح من فضلك؟","meaning":"Kontextbeispiel"},{"text":"ربما يكون هذا خيارا مناسبا.","meaning":"Kontextbeispiel"}],"terms":[],"grammar_notes":[],"aliases":[]}'::jsonb,ARRAY['تهذيب','احتمال','نفي','تقييد','مقابلة'],'foundational','active','original_authored','messinho_original'),
('ar-tn.grammar.sentence',1,'ar-tn','grammar','Derja Satzbau','Grundmuster der tunesischen Derja','{"explanation":"Tunesische Derja ist eine eigenständige gesprochene Varietät mit regionalen und situativen Unterschieden. Die Wortstellung ist häufig Subjekt–Verb–Objekt, kann aber durch Fokus und Gesprächskontext variieren. Hocharabische Formen dürfen nicht automatisch als alltägliche Derja behandelt werden.","examples":[{"text":"Ena nheb el koura. — Ich mag Fußball.","meaning":"Beispiel zur grammatischen oder pragmatischen Anwendung"},{"text":"Houwa yelعب barcha. — Er spielt viel.","meaning":"Kontextbeispiel"}],"terms":[],"grammar_notes":[],"aliases":[]}'::jsonb,ARRAY['Derja','Wortstellung','Kontext','Dialekt'],'foundational','active','original_authored','messinho_original'),
('ar-tn.grammar.negation',1,'ar-tn','grammar','Negation','Verneinung mit ma- ... -sh','{"explanation":"Eine häufige tunesische Verneinungsform setzt ma- vor das Verb und -sh nach das Verb. Die Form und Verwendung können je nach Verb, Region und Gespräch variieren; nicht jede Negation folgt ausnahmslos demselben Muster.","examples":[{"text":"Ma fhemtch. — Ich habe nicht verstanden.","meaning":"Beispiel zur grammatischen oder pragmatischen Anwendung"},{"text":"Ma nhebbech. — Ich möchte nicht.","meaning":"Kontextbeispiel"},{"text":"Ma jéch. — Er ist nicht gekommen.","meaning":"Kontextbeispiel"}],"terms":[],"grammar_notes":[],"aliases":[]}'::jsonb,ARRAY['ma','sh','ch','negation','Verneinung'],'foundational','active','original_authored','messinho_original'),
('ar-tn.grammar.pronouns',1,'ar-tn','grammar','Pronomen und Verbformen','Personenbezug in Derja','{"explanation":"Person und Bezug werden oft durch Verbformen und angehängte Pronomen markiert. Arabische Schrift und lateinische Arabizi-Umschrift können dieselbe Äußerung unterschiedlich darstellen. Arabizi-Ziffern wie 3, 5, 7 und 9 werden in informeller Umschrift für arabische Laute verwendet.","examples":[{"text":"Ena — ich","meaning":"Beispiel zur grammatischen oder pragmatischen Anwendung"},{"text":"Enti — du (weiblich)","meaning":"Kontextbeispiel"},{"text":"Enta — du (männlich)","meaning":"Kontextbeispiel"},{"text":"Nheb — ich möchte / liebe","meaning":"Kontextbeispiel"}],"terms":[],"grammar_notes":[],"aliases":[]}'::jsonb,ARRAY['pronomen','person','Arabizi','Umschrift'],'foundational','active','original_authored','messinho_original'),
('ar-tn.lexicon.core',1,'ar-tn','lexicon','Derja Wortschatz','Häufige tunesische Gesprächswörter','{"explanation":"Erste selbst formulierte Auswahl tunesischer Wörter und Wendungen. Die Schreibweise ist nicht standardisiert; Varianten in Arabizi sind normal. Bedeutung muss aus Satz und Situation erschlossen werden.","examples":[],"terms":[{"term":"عسلامة / aslema — hallo","meaning_de":"Kontextabhängige Bedeutung; im Satz prüfen."},{"term":"لاباس / labes — alles gut?","meaning_de":"Kontextabhängige Bedeutung; im Satz prüfen."},{"term":"شنوة / chnowa — was?","meaning_de":"Kontextabhängige Bedeutung; im Satz prüfen."},{"term":"علاش / alech — warum?","meaning_de":"Kontextabhängige Bedeutung; im Satz prüfen."},{"term":"برشا / barcha — viel / sehr","meaning_de":"Kontextabhängige Bedeutung; im Satz prüfen."},{"term":"ياسر / yesser — sehr","meaning_de":"Kontextabhängige Bedeutung; im Satz prüfen."},{"term":"فما / fama — es gibt","meaning_de":"Kontextabhängige Bedeutung; im Satz prüfen."},{"term":"توا / taw — jetzt","meaning_de":"Kontextabhängige Bedeutung; im Satz prüfen."},{"term":"وين / win — wo?","meaning_de":"Kontextabhängige Bedeutung; im Satz prüfen."},{"term":"قداش / 9addech — wie viel?","meaning_de":"Kontextabhängige Bedeutung; im Satz prüfen."},{"term":"مريقل / mrigel — gut / in Ordnung","meaning_de":"Kontextabhängige Bedeutung; im Satz prüfen."},{"term":"باهي / behi — gut","meaning_de":"Kontextabhängige Bedeutung; im Satz prüfen."}],"grammar_notes":[],"aliases":[]}'::jsonb,ARRAY['عسلامة / aslema — hallo','لاباس / labes — alles gut?','شنوة / chnowa — was?','علاش / alech — warum?','برشا / barcha — viel / sehr','ياسر / yesser — sehr','فما / fama — es gibt','توا / taw — jetzt','وين / win — wo?','قداش / 9addech — wie viel?','مريقل / mrigel — gut / in Ordnung','باهي / behi — gut'],'foundational','active','original_authored','messinho_original'),
('ar-tn.pragmatics.dialogue',1,'ar-tn','pragmatics','Derja Gesprächsverständnis','Dialekt, Höflichkeit und Sprachwechsel','{"explanation":"Derja enthält häufig französische Lehnwörter und Wechsel zwischen Arabisch und Französisch. Eine informelle Schreibweise ist nicht automatisch falsch. MESSINHO soll den Sinn erhalten, bei echter Mehrdeutigkeit nachfragen und nicht ungefragt in Hocharabisch umformen.","examples":[{"text":"Aslema, labes? — Hallo, alles gut?","meaning":"Beispiel zur grammatischen oder pragmatischen Anwendung"},{"text":"Chnowa rayek? — Was meinst du?","meaning":"Kontextbeispiel"},{"text":"Barcha behi — sehr gut","meaning":"Kontextbeispiel"}],"terms":[],"grammar_notes":[],"aliases":[]}'::jsonb,ARRAY['code-switching','französische Lehnwörter','Arabizi','Höflichkeit'],'foundational','active','original_authored','messinho_original'),
('es.grammar.word_order',1,'es','grammar','Orden de palabras','Sujeto, verbo y complemento','{"explanation":"El orden más habitual de una oración declarativa es sujeto–verbo–complemento, pero el español permite omitir el sujeto cuando la forma verbal lo identifica. El orden puede cambiar para destacar información.","examples":[{"text":"El jugador entrena hoy.","meaning":"Beispiel zur grammatischen oder pragmatischen Anwendung"},{"text":"Entrenamos mañana.","meaning":"Kontextbeispiel"},{"text":"Hoy juega el equipo.","meaning":"Kontextbeispiel"}],"terms":[],"grammar_notes":[],"aliases":[]}'::jsonb,ARRAY['sujeto','verbo','complemento','énfasis'],'foundational','active','original_authored','messinho_original'),
('es.grammar.gender_agreement',1,'es','grammar','Género y concordancia','Género y número','{"explanation":"Los sustantivos tienen género gramatical y los determinantes y adjetivos concuerdan normalmente en género y número. La terminación de una palabra ayuda, pero no determina siempre el género.","examples":[{"text":"un jugador rápido","meaning":"Beispiel zur grammatischen oder pragmatischen Anwendung"},{"text":"una jugadora rápida","meaning":"Kontextbeispiel"},{"text":"los jugadores rápidos","meaning":"Kontextbeispiel"}],"terms":[],"grammar_notes":[],"aliases":[]}'::jsonb,ARRAY['masculino','femenino','singular','plural','concordancia'],'foundational','active','original_authored','messinho_original'),
('es.grammar.verbs',1,'es','grammar','Conjugación','Persona, tiempo y modo','{"explanation":"La forma verbal expresa persona, número, tiempo y modo. El pretérito perfecto simple presenta normalmente un hecho pasado y terminado; el imperfecto describe hábitos, estados o procesos en el pasado. El contexto determina la interpretación.","examples":[{"text":"Jugó ayer.","meaning":"Beispiel zur grammatischen oder pragmatischen Anwendung"},{"text":"Ha mejorado esta temporada.","meaning":"Kontextbeispiel"},{"text":"Cuando era joven, entrenaba mucho.","meaning":"Kontextbeispiel"}],"terms":[],"grammar_notes":[],"aliases":[]}'::jsonb,ARRAY['presente','pretérito','imperfecto','perfecto','modo'],'foundational','active','original_authored','messinho_original'),
('es.lexicon.core',1,'es','lexicon','Vocabulario frecuente','Palabras habituales de conversación','{"explanation":"Vocabulario original de inicio para conversaciones naturales. Algunas palabras cambian de sentido según el país, el registro y la expresión completa.","examples":[],"terms":[{"term":"aunque","meaning_de":"Kontextabhängige Bedeutung; im Satz prüfen."},{"term":"sin embargo","meaning_de":"Kontextabhängige Bedeutung; im Satz prüfen."},{"term":"todavía","meaning_de":"Kontextabhängige Bedeutung; im Satz prüfen."},{"term":"ya","meaning_de":"Kontextabhängige Bedeutung; im Satz prüfen."},{"term":"quizás","meaning_de":"Kontextabhängige Bedeutung; im Satz prüfen."},{"term":"más bien","meaning_de":"Kontextabhängige Bedeutung; im Satz prüfen."},{"term":"por tanto","meaning_de":"Kontextabhängige Bedeutung; im Satz prüfen."},{"term":"aun así","meaning_de":"Kontextabhängige Bedeutung; im Satz prüfen."},{"term":"mientras","meaning_de":"Kontextabhängige Bedeutung; im Satz prüfen."},{"term":"sino","meaning_de":"Kontextabhängige Bedeutung; im Satz prüfen."},{"term":"rendimiento","meaning_de":"Kontextabhängige Bedeutung; im Satz prüfen."},{"term":"desarrollo","meaning_de":"Kontextabhängige Bedeutung; im Satz prüfen."},{"term":"fortaleza","meaning_de":"Kontextabhängige Bedeutung; im Satz prüfen."},{"term":"debilidad","meaning_de":"Kontextabhängige Bedeutung; im Satz prüfen."},{"term":"evaluación","meaning_de":"Kontextabhängige Bedeutung; im Satz prüfen."}],"grammar_notes":[],"aliases":[]}'::jsonb,ARRAY['aunque','sin embargo','todavía','ya','quizás','más bien','por tanto','aun así','mientras','sino','rendimiento','desarrollo','fortaleza','debilidad','evaluación'],'foundational','active','original_authored','messinho_original'),
('es.pragmatics.dialogue',1,'es','pragmatics','Pragmática','Matices y cortesía','{"explanation":"Palabras como todavía, quizás, aunque, sin embargo y más bien expresan reserva, contraste o incertidumbre. Una pregunta cortés puede funcionar como petición indirecta. Hay que conservar la negación y los matices.","examples":[{"text":"Es bueno, pero todavía no está preparado.","meaning":"Beispiel zur grammatischen oder pragmatischen Anwendung"},{"text":"¿Podrías explicarlo, por favor?","meaning":"Kontextbeispiel"},{"text":"Quizás sea una buena opción.","meaning":"Kontextbeispiel"}],"terms":[],"grammar_notes":[],"aliases":[]}'::jsonb,ARRAY['atenuación','cortesía','contraste','implicatura'],'foundational','active','original_authored','messinho_original')
