-- MESSINHO six-language linguistic knowledge foundation.
-- Original-authored compact rules and starter vocabulary; no copied dictionary text.
-- Apply to dedicated STAGING only. Rows are append-only, versioned, and server-only.
create table if not exists public.messinho_language_knowledge (
  entry_key text not null check (entry_key ~ '^[a-z0-9][a-z0-9._-]{2,159}$'),
  version integer not null check (version > 0),
  language_code text not null check (language_code in ('de','en','fr','ar','ar-tn','es','shared')),
  entry_type text not null check (entry_type in ('grammar','lexicon','pragmatics','conversation')),
  topic text not null check (char_length(topic) between 2 and 160),
  title text not null check (char_length(title) between 3 and 220),
  content jsonb not null check (jsonb_typeof(content)='object' and octet_length(content::text)<=12000),
  tags text[] not null default '{}',
  level text not null check (level in ('foundational','intermediate','advanced','specialist')),
  knowledge_status text not null check (knowledge_status in ('active','candidate','superseded','quarantined')),
  provenance_type text not null check (provenance_type in ('original_authored','licensed_source')),
  created_by text not null,
  created_at timestamptz not null default now(),
  primary key(entry_key,version)
);
create index if not exists messinho_language_knowledge_language_status_idx
  on public.messinho_language_knowledge(language_code,knowledge_status,entry_type);
create index if not exists messinho_language_knowledge_tags_idx
  on public.messinho_language_knowledge using gin(tags);
alter table public.messinho_language_knowledge enable row level security;
revoke all on public.messinho_language_knowledge from public,anon,authenticated,service_role;
grant select on public.messinho_language_knowledge to service_role;
comment on table public.messinho_language_knowledge is 'MESSINHO original-authored multilingual grammar, vocabulary and pragmatics. Append-only version rows; service-role read-only at runtime; no direct Scout/Admin writes.';
on conflict(entry_key,version) do nothing;
